SPEC = MUTABLE['model']
_scalar_valid_state = valid_state
_scalar_execute = execute
_scalar_value_of = value_of


def value_of(assignment, inputs):
    return copy.deepcopy(_scalar_value_of(assignment, inputs))


def mutable_value_valid(value, typ):
    if typ["type"] == "collection":
        return (type(value) is list and all(mutable_value_valid(x, typ["element"]) for x in value)
                and (typ["duplicates"] == "allow" or mutable_unique(value) == value))
    if value is None:
        return typ.get("nullable", False)
    if type(value) is not str:
        return False
    if typ["type"] == "enum":
        return value in typ["domain"]
    return utc_timestamp(value) if typ["type"] == "timestamp" else typ["type"] in ("string", "identifier")


def mutable_unique(values):
    result = []
    for value in values:
        if value not in result:
            result.append(value)
    return result


def valid_state(records, state, record_type):
    if type(records) is not list:
        return False
    names = {f["name"] for f in record_type["fields"]}
    if any(type(r) is not dict or set(r) != names or any(not mutable_value_valid(r[n], t) for n, t in MUTABLE["value_types"].items()) for r in records):
        return False
    collection_names = {c["name"] for c in MUTABLE["facts"]["collections"]}
    scalar_type = {**record_type, "fields": [f for f in record_type["fields"] if f["name"] not in collection_names]}
    return _scalar_valid_state([{k: v for k, v in r.items() if k not in collection_names} for r in records], state, scalar_type)


def mutable_pipeline(value, steps, typ, error):
    value = copy.deepcopy(value)
    # Raw shape must be safe for transformations. Uniqueness is validated at the
    # final/stated typed stage, so explicitly authorized dedup can repair it.
    shape_ok = (type(value) is list and all(type(x) is str for x in value)) if typ["type"] == "collection" else (type(value) is str or (value is None and typ.get("nullable", False)))
    if not shape_ok:
        raise Failure(error)
    for step in steps:
        if step["kind"] == "map_elements":
            value = [mutable_pipeline(x, step["pipeline"], typ["element"], error) for x in value]
        elif step["kind"] == "transform":
            if step["operation"] == "trim":
                if value is None:
                    raise Failure(error)
                value = value.strip()
            elif step["operation"] == "stable_deduplicate":
                value = mutable_unique(value)
        else:
            rule = step["rule"]
            ok = mutable_value_valid(value, typ) if rule == "typed" else bool(value) if rule == "nonempty" else (type(value) is str and bool(value.strip()))
            if not ok:
                raise Failure(step["error"])
    if not mutable_value_valid(value, typ):
        raise Failure(error)
    return value


def execute_mutation(mutation, inputs):
    state = SPEC["state"][0]
    record_type, path = state_layout(state)
    records = read_state(state, record_type, path)
    key = mutation["lookup"]
    target = next((r for r in records if r[key] == inputs.get(key)), None)
    if target is None:
        raise Failure(mutation["missing_error"])
    for guard in mutation["guards"]:
        if target[guard["field"]] != guard["value"]:
            raise Failure(guard["error"])
    candidate = copy.deepcopy(target)
    for change in mutation["changes"]:
        supplied = change["input"] in inputs
        if not supplied:
            if change["omitted"] == "reject":
                raise Failure(change["missing_error"])
            continue
        typ = MUTABLE["value_types"][change["field"]]
        value = mutable_pipeline(inputs[change["input"]], change["pipeline"], typ if change["operation"] == "replace" else typ["element"], change["invalid_error"])
        if change["operation"] == "replace":
            candidate[change["field"]] = value
        elif change["operation"] == "append" or value not in candidate[change["field"]]:
            candidate[change["field"]].append(value)
        if not mutable_value_valid(candidate[change["field"]], typ):
            raise Failure(change["invalid_error"])
    staged = [candidate if r is target else copy.deepcopy(r) for r in records]
    write_state(staged, state, record_type, path)
    return copy.deepcopy(candidate)


def execute(behavior, inputs, clock=None, *, providers=None):
    inputs = copy.deepcopy(inputs)
    if behavior["kind"] == "create":
        pipelines = MUTABLE["facts"]["creation_pipelines"] + [dict(field=c["name"], pipeline=c["creation"]["pipeline"], error=c["creation"]["error"]) for c in MUTABLE["facts"]["collections"]]
        for p in pipelines:
            field = next(f for f in MUTABLE["model"]["types"] if f["kind"] == "record")["fields"]
            fid = next(f["id"] for f in field if f["name"] == p["field"])
            assignment = next(a for a in behavior["assignments"] if a["field"] == fid)
            iid = assignment["id"]
            if iid in inputs:
                inputs[iid] = mutable_pipeline(inputs[iid], p["pipeline"], MUTABLE["value_types"][p["field"]], p["error"])
    return _scalar_execute(behavior, inputs, clock, providers=providers)


def mutable_main(argv=None):
    parser = argparse.ArgumentParser(prog=SPEC["application"]["name"])
    commands = parser.add_subparsers(dest="command", required=True)
    mutations = {m["command"]: m for m in MUTABLE["facts"]["mutations"]}
    for c in SPEC["commands"]:
        sub = commands.add_parser(c["token"])
        if "migration" not in c:
            b = by_id("behaviors", c["behavior"])
            for arg in c["arguments"]:
                decl = next((x for x in MUTABLE["facts"]["collections"] if x["creation"]["input"] == arg["flag"][2:].replace("-", "_") and b["kind"] == "create"), None)
                sub.add_argument(arg["flag"], required=arg["required"], default=argparse.SUPPRESS, **({"action": "append"} if decl and decl["creation"]["encoding"] == "repeated" else {}))
    for token, m in mutations.items():
        sub = commands.add_parser(token)
        sub.add_argument("--" + m["lookup"].replace("_", "-"), required=True)
        for w in m["changes"]:
            sub.add_argument("--" + w["input"].replace("_", "-"), default=argparse.SUPPRESS)
    parsed = vars(parser.parse_args(argv)); token = parsed.pop("command")
    try:
        if token in mutations:
            m = mutations[token]
            for w in m["changes"]:
                if w["input"] in parsed and w["operation"] == "replace" and MUTABLE["value_types"][w["field"]]["type"] == "collection":
                    try:
                        parsed[w["input"]] = json.loads(parsed[w["input"]])
                    except ValueError:
                        raise Failure(w["invalid_error"])
            result = execute_mutation(m, parsed)
        else:
            c = next(c for c in SPEC["commands"] if c["token"] == token)
            if "migration" in c:
                result = migrate()
            else:
                b = by_id("behaviors", c["behavior"]); inputs = {}
                for arg in c["arguments"]:
                    n = arg["flag"][2:].replace("-", "_")
                    if n not in parsed:
                        continue
                    value = parsed[n]
                    decl = next((x for x in MUTABLE["facts"]["collections"] if x["creation"]["input"] == n and b["kind"] == "create"), None)
                    if decl and decl["creation"]["encoding"] == "json":
                        try:
                            value = json.loads(value)
                        except ValueError:
                            raise Failure(decl["creation"]["error"])
                    inp = next(i for i in b["inputs"] if i["id"] == arg["input"])
                    if inp["type"] not in ("prim:string", "prim:timestamp") and by_id("types", inp["type"])["kind"] == "enum" and value not in by_id("types", inp["type"])["values"]:
                        parser.error("invalid choice: " + value)
                    inputs[arg["input"]] = value
                result = execute(b, inputs)
        print(json.dumps(result, sort_keys=True, ensure_ascii=False))
        return 0
    except Failure as exc:
        print(json.dumps({"error": exc.code}), file=sys.stderr)
        return 1


main = mutable_main


legacy_main = main
"""Trusted query backend template: standalone standard-library JSON subprocess."""
import argparse
import copy
import json
import sys
from pathlib import Path


class ApplicationError(Exception):
    pass


def matches_type(value, kind):
    return ((kind == "string" and type(value) is str) or
            (kind == "integer" and type(value) is int) or
            (kind == "boolean" and type(value) is bool) or
            (kind == "strings" and type(value) is list and all(type(x) is str for x in value)))


def execute_query(model, records, inputs):
    # Input validation precedes selection and never rewrites the parameter value.
    if set(inputs) != set(model["parameters"]) or any(type(v) is not str for v in inputs.values()):
        raise ApplicationError("invalid_input")
    for rule in model["validation"]:
        value = inputs[rule["parameter"]]
        if (rule["rule"] == "nonempty" and value == "") or (rule["rule"] == "nonblank" and not value.strip()):
            raise ApplicationError(rule["error"])
    fields = model["source"]["fields"]
    identity = model["source"]["unique_key"]
    if type(records) is not list:
        raise ApplicationError("invalid_state")
    seen = set()
    for record in records:
        if (type(record) is not dict or set(record) != set(fields) or
                any(not matches_type(record[k], v) for k, v in fields.items()) or record[identity] in seen):
            raise ApplicationError("invalid_state")
        seen.add(record[identity])

    pred = model["predicate"]
    operand = pred["operand"]
    target = inputs[operand["parameter"]] if "parameter" in operand else operand["constant"]
    def compare_value(value):
        if model["comparison"]["normalization"] == "strip":
            value = value.strip()
        if model["comparison"]["case"] == "casefold":
            value = value.casefold()
        return value
    target = compare_value(target)
    selected = []
    for record in records:
        values = record[pred["field"]] if pred["operator"] == "contains" else [record[pred["field"]]]
        if not any(compare_value(v) == target for v in values):
            continue
        if any(rule["mode"] == "equals" and record[rule["field"]] != rule["value"] for rule in model["inclusion"]):
            continue
        selected.append(copy.deepcopy(record))
    # Stable sorts from least to most significant key preserve key precedence.
    for key in reversed(model["ordering"]):
        selected.sort(key=lambda r: r[key["field"]], reverse=key["direction"] == "DESC")
    if not selected:
        behavior = model["result"]["no_match"]
        if behavior == "error":
            raise ApplicationError(model["result"]["error"])
        if behavior == "null":
            return None
    return selected


def standalone_query_main(model):
    parser = argparse.ArgumentParser()
    parser.add_argument("--store", required=True)
    for name in model["parameters"]:
        parser.add_argument("--" + name, required=True)
    args = vars(parser.parse_args())
    path = Path(args.pop("store"))
    try:
        # Read only: no mkdir, migration, initialization or write path exists.
        records = json.loads(path.read_text(encoding="utf-8")) if path.exists() else []
        result = execute_query(model, records, args)
        print(json.dumps(result, ensure_ascii=False))
    except (OSError, ValueError):
        print(json.dumps({"error": "invalid_state"}), file=sys.stderr)
        sys.exit(1)
    except ApplicationError as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        sys.exit(1)

"""Generated normal query dispatcher and read-only collection-view adapter."""


def profile_main(queries, storage):
    models = {q["id"]: q for q in queries}
    if storage["kind"] in ("model_state", "mutable_state") and len(sys.argv) > 1 and sys.argv[1] not in models:
        return legacy_main()
    parser = argparse.ArgumentParser(prog="lykoi")
    commands = parser.add_subparsers(dest="command", required=True)
    for q in queries:
        sub = commands.add_parser(q["id"])
        if storage["kind"] == "json_array":
            sub.add_argument("--store", required=True)
        for name in q["parameters"]:
            sub.add_argument("--" + name, required=True)
    args = vars(parser.parse_args())
    model = models[args.pop("command")]
    try:
        # Declared runtime validation is independent of persisted record validity.
        for rule in model["validation"]:
            value = args[rule["parameter"]]
            if ((rule["rule"] == "nonempty" and value == "") or
                    (rule["rule"] == "nonblank" and not value.strip())):
                raise ApplicationError(rule["error"])
        if storage["kind"] == "json_array":
            path = Path(args.pop("store"))
            records = json.loads(path.read_text(encoding="utf-8")) if path.exists() else []
            result = execute_query(model, records, args)
        else:
            state = by_id("state", storage["state"])
            record_type, path = state_layout(state)
            records = read_state(state, record_type, path)
            # Validate the full legacy store before projecting the supported view.
            # Nonquery nullable fields survive unchanged; no nullable predicate.
            view = [{k: r[k] for k in model["source"]["fields"]} for r in records]
            selected = execute_query(model, view, args)
            key = model["source"]["unique_key"]
            originals = {r[key]: r for r in records}
            result = None if selected is None else [copy.deepcopy(originals[r[key]]) for r in selected]
        print(json.dumps(result, ensure_ascii=False))
        return 0
    except ApplicationError as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 1
    except (OSError, ValueError):
        print(json.dumps({"error": "invalid_state"}), file=sys.stderr)
        return 1
    except globals().get("Failure", ApplicationError) as exc:
        print(json.dumps({"error": exc.code}), file=sys.stderr)
        return 1

if __name__ == '__main__':
